# -*- coding: utf-8 -*-
from odoo import models, fields, api

class ProductProduct(models.Model):
    _name = 'product.product'
    _description = 'PRODUCT PRODUCT'
    _order = 'id desc'

    activity_ids = fields.One2many(comodel_name="mail.activity", inverse_name='parent_id', string="Activities")
    activity_state = fields.Selection(selection=[["overdue","Overdue"],["today","Today"],["planned","Planned"]], string="Activity State", readonly=True, help="Status based on activities\nOverdue: Due date is already passed\nToday: Activity date is today\nPlanned: Future activities.")
    activity_user_id = fields.Many2one(comodel_name="res.users", string="Responsible User")
    activity_type_id = fields.Many2one(comodel_name="mail.activity.type", string="Next Activity Type")
    activity_type_icon = fields.Char(string="Activity Type Icon", readonly=True, help="Font awesome icon e.g. fa-tasks")
    activity_date_deadline = fields.Date(string="Next Activity Deadline", readonly=True)
    my_activity_date_deadline = fields.Date(string="My Activity Deadline", readonly=True)
    activity_summary = fields.Char(string="Next Activity Summary")
    activity_exception_decoration = fields.Selection(selection=[["warning","Alert"],["danger","Error"]], string="Activity Exception Decoration", readonly=True, help="Type of the exception activity on record.")
    activity_exception_icon = fields.Char(string="Icon", readonly=True, help="Icon to indicate an exception activity.")
    activity_calendar_event_id = fields.Many2one(comodel_name="calendar.event", string="Next Activity Calendar Event", readonly=True)
    message_is_follower = fields.Boolean(string="Is Follower", readonly=True)
    message_follower_ids = fields.One2many(comodel_name="mail.followers", inverse_name='parent_id', string="Followers")
    message_partner_ids = fields.Many2many(comodel_name="res.partner", string="Followers (Partners)")
    message_ids = fields.One2many(comodel_name="mail.message", inverse_name='parent_id', string="Messages")
    has_message = fields.Boolean(string="Has Message", readonly=True)
    message_needaction = fields.Boolean(string="Action Needed", readonly=True, help="If checked, new messages require your attention.")
    message_needaction_counter = fields.Integer(string="Number of Actions", readonly=True, help="Number of messages requiring action")
    message_has_error = fields.Boolean(string="Message Delivery error", readonly=True, help="If checked, some messages have a delivery error.")
    message_has_error_counter = fields.Integer(string="Number of errors", readonly=True, help="Number of messages with delivery error")
    message_attachment_count = fields.Integer(string="Attachment Count", readonly=True)
    message_main_attachment_id = fields.Many2one(comodel_name="ir.attachment", string="Main Attachment")
    website_message_ids = fields.One2many(comodel_name="mail.message", inverse_name='parent_id', string="Website Messages", help="Website communication history")
    message_has_sms_error = fields.Boolean(string="SMS Delivery error", readonly=True, help="If checked, some messages have a delivery error.")
    price_extra = fields.Float(string="Variant Price Extra", readonly=True, help="This is the sum of the extra price of all attributes")
    lst_price = fields.Float(string="Sales Price", help="The sale price is managed from the product template. Click on the 'Configure Variants' button to set the extra attribute prices.")
    default_code = fields.Char(string="Code")
    code = fields.Char(string="Reference", readonly=True)
    partner_ref = fields.Char(string="Customer Ref", readonly=True)
    active = fields.Boolean(string="Active", help="If unchecked, it will allow you to hide the product without removing it.")
    product_tmpl_id = fields.Many2one(comodel_name="product.template", string="Product Template", required=True)
    barcode = fields.Char(string="Barcode", help="International Article Number used for product identification.")
    product_template_attribute_value_ids = fields.Many2many(comodel_name="product.template.attribute.value", string="Attribute Values")
    product_template_variant_value_ids = fields.Many2many(comodel_name="product.template.attribute.value", string="Variant Values")
    combination_indices = fields.Char(string="Combination Indices", readonly=True)
    is_product_variant = fields.Boolean(string="Is Product Variant", readonly=True)
    standard_price = fields.Float(string="Cost", help="In Standard Price & AVCO: value of the product (automatically computed in AVCO).\n        In FIFO: value of the next unit that will leave the stock (automatically computed).\n        Used to value the product when the purchase cost is not known (e.g. inventory adjustment).\n        Used to compute margins on sale orders.")
    volume = fields.Float(string="Volume")
    weight = fields.Float(string="Weight")
    pricelist_item_count = fields.Integer(string="Number of price rules", readonly=True)
    packaging_ids = fields.One2many(comodel_name="product.packaging", inverse_name='parent_id', string="Product Packages", help="Gives the different ways to package the same product.")
    additional_product_tag_ids = fields.Many2many(comodel_name="product.tag", string="Additional Product Tag")
    all_product_tag_ids = fields.Many2many(comodel_name="product.tag", string="All Product Tag", readonly=True)
    image_variant_1920 = fields.Binary(string="Variant Image")
    image_variant_1024 = fields.Binary(string="Variant Image 1024", readonly=True)
    image_variant_512 = fields.Binary(string="Variant Image 512", readonly=True)
    image_variant_256 = fields.Binary(string="Variant Image 256", readonly=True)
    image_variant_128 = fields.Binary(string="Variant Image 128", readonly=True)
    can_image_variant_1024_be_zoomed = fields.Boolean(string="Can Variant Image 1024 be zoomed", readonly=True)
    image_1920 = fields.Binary(string="Image")
    image_1024 = fields.Binary(string="Image 1024", readonly=True)
    image_512 = fields.Binary(string="Image 512", readonly=True)
    image_256 = fields.Binary(string="Image 256", readonly=True)
    image_128 = fields.Binary(string="Image 128", readonly=True)
    can_image_1024_be_zoomed = fields.Boolean(string="Can Image 1024 be zoomed", readonly=True)
    tax_string = fields.Char(string="Tax String", readonly=True)
    standard_price_update_warning = fields.Char(string="Standard Price Update Warning", readonly=True)
    other_name = fields.Char(string="English Name")
    name = fields.Char(string="Name", required=True)
    sequence = fields.Integer(string="Sequence", help="Gives the sequence order when displaying a product list")
    description = fields.Html(string="Description")
    description_purchase = fields.Text(string="Purchase Description")
    description_sale = fields.Text(string="Sales Description", help="A description of the Product that you want to communicate to your customers. This description will be copied to every Sales Order, Delivery Order and Customer Invoice/Credit Note")
    detailed_type = fields.Selection(selection=[["consu","Consumable"],["service","Service"]], string="Product Type", required=True, help="A storable product is a product for which you manage stock. The Inventory app has to be installed.\nA consumable product is a product for which stock is not managed.\nA service is a non-material product you provide.")
    type = fields.Selection(selection=[["consu","Consumable"],["service","Service"]], string="Type")
    categ_id = fields.Many2one(comodel_name="product.category", string="Product Category", required=True)
    currency_id = fields.Many2one(comodel_name="res.currency", string="Currency", readonly=True)
    cost_currency_id = fields.Many2one(comodel_name="res.currency", string="Cost Currency", readonly=True)
    list_price = fields.Float(string="Sales Price", help="Price at which the product is sold to customers.")
    volume_uom_name = fields.Char(string="Volume unit of measure label", readonly=True)
    weight_uom_name = fields.Char(string="Weight unit of measure label", readonly=True)
    sale_ok = fields.Boolean(string="Can be Sold")
    purchase_ok = fields.Boolean(string="Can be Purchased")
    uom_id = fields.Many2one(comodel_name="uom.uom", string="Unit of Measure", required=True, help="Default unit of measure used for all stock operations.")
    uom_name = fields.Char(string="Unit of Measure Name", readonly=True)
    uom_po_id = fields.Many2one(comodel_name="uom.uom", string="Purchase UoM", required=True, help="Default unit of measure used for purchase orders. It must be in the same category as the default unit of measure.")
    company_id = fields.Many2one(comodel_name="res.company", string="Company")
    seller_ids = fields.One2many(comodel_name="product.supplierinfo", inverse_name='parent_id', string="Vendors")
    variant_seller_ids = fields.One2many(comodel_name="product.supplierinfo", inverse_name='parent_id', string="Variant Seller")
    color = fields.Integer(string="Color Index")
    attribute_line_ids = fields.One2many(comodel_name="product.template.attribute.line", inverse_name='parent_id', string="Product Attributes")
    valid_product_template_attribute_line_ids = fields.Many2many(comodel_name="product.template.attribute.line", string="Valid Product Attribute Lines", readonly=True)
    product_variant_ids = fields.One2many(comodel_name="product.product", inverse_name='parent_id', string="Products", required=True)
    product_variant_id = fields.Many2one(comodel_name="product.product", string="Product", readonly=True)
    product_variant_count = fields.Integer(string="# Product Variants", readonly=True)
    has_configurable_attributes = fields.Boolean(string="Is a configurable product", readonly=True)
    product_tooltip = fields.Char(string="Product Tooltip", readonly=True)
    priority = fields.Selection(selection=[["0","Normal"],["1","Favorite"]], string="Favorite")
    product_tag_ids = fields.Many2many(comodel_name="product.tag", string="Product Tags")
    taxes_id = fields.Many2many(comodel_name="account.tax", string="Customer Taxes", help="Default taxes used when selling the product.")
    supplier_taxes_id = fields.Many2many(comodel_name="account.tax", string="Vendor Taxes", help="Default taxes used when buying the product.")
    property_account_income_id = fields.Many2one(comodel_name="account.account", string="Income Account", help="Keep this field empty to use the default value from the product category.")
    property_account_expense_id = fields.Many2one(comodel_name="account.account", string="Expense Account", help="Keep this field empty to use the default value from the product category. If anglo-saxon accounting with automated valuation method is configured, the expense account on the product category will be used.")
    account_tag_ids = fields.Many2many(comodel_name="account.account.tag", string="Account Tags", help="Tags to be set on the base and tax journal items created for this product.")
    can_be_expensed = fields.Boolean(string="Can be Expensed", help="Specify whether the product can be selected in an expense.")
    asset_category_id = fields.Many2one(comodel_name="account.asset.category", string="Asset Category")
    deferred_revenue_category_id = fields.Many2one(comodel_name="account.asset.category", string="Deferred Revenue Type")
    freight_type = fields.Selection(selection=[["route","Route"],["service","Service"]], string="Freight Type")
    transport_mode_ids = fields.Many2many(comodel_name="freight.transport.mode", string="Transport Modes")
    freight_port_pol_id = fields.Many2one(comodel_name="freight.port", string="Port Of Loading (POL)")
    freight_port_pod_id = fields.Many2one(comodel_name="freight.port", string="Port Of Discharge (POD)")
    freight_country_id = fields.Many2one(comodel_name="res.country", string="Country", readonly=True)
    freight_port_of_receipt_id = fields.Many2one(comodel_name="freight.port", string="Place of Receipt")
    freight_port_of_delivery_id = fields.Many2one(comodel_name="freight.port", string="Place of Delivery")
    freight_service_type = fields.Selection(selection=[["freight","Freight"],["surcharge","Surcharge"],["local_charge","Local Charge"],["inland_charge","Inland Charge"],["logistic_charge","Logistic Charge"],["pay_on_behalf","Pay On Behalf"]], string="Service Type")
    default_tax_id = fields.Many2one(comodel_name="account.tax", string="Default Sale Tax")
    charge_scope = fields.Selection(selection=[["domestic","Domestic"],["oversea","Oversea"]], string="Charge Scope", help="Where the charge is incurred: in the company's country (Domestic) or abroad (Oversea). Used as the default on quotation Other Charges lines.")
    local_name = fields.Char(string="Local Name")
    is_com_fee = fields.Boolean(string="Is Com Fee")
    freight_qty_rule_ids = fields.One2many(comodel_name="freight.product.qty.rule", inverse_name='parent_id', string="Quantity Rules")
    show_plate_number = fields.Boolean(string="Show Plate Number", help="Trucking fare: invoice lines show the truck plate number, are named by route and grouped by route on SOA invoices.")
    show_customs_declaration_no = fields.Boolean(string="Show Customs Declaration No.", help="Customs fare: invoice line names show the customs declaration number(s).")
    job_profit_group = fields.Selection(selection=[["cuoc","Cước"],["local","Local"],["haiquan","Hải quan"],["trucking","Vận chuyển"],["chingoai","Chi ngoài"],["com","Hoa hồng"],["chiho","Chi hộ"]], string="Job Profit Group", help="Nhóm phí dùng cho báo cáo Job Profit by Perf. Date. Để trống: hệ thống tự phân loại theo cách cũ.")
    is_com_customer_fee = fields.Boolean(string="Is Com Customer Fee")
